import { render, screen } from '@testing-library/react'
import { describe, expect, it, vi } from 'vitest'
import { IssueListPage } from '../pages/IssueListPage'
import { installFakeApi, jsonResponse } from './fakeApi'

describe('IssueListPage (reading data)', () => {
  it('shows a loading message first, then the issues from the API', async () => {
    installFakeApi()
    render(<IssueListPage />)

    expect(screen.getByRole('status')).toHaveTextContent(/loading/i)
    expect(await screen.findByText('Showing 4 of 4 issues')).toBeInTheDocument()
    expect(screen.getByRole('heading', { name: 'Login button does nothing' })).toBeInTheDocument()
    expect(screen.queryByRole('status')).not.toBeInTheDocument()
  })

  it('asks the API for the issues exactly once', async () => {
    const { fetchMock } = installFakeApi()
    render(<IssueListPage />)
    await screen.findByText('Showing 4 of 4 issues')
    expect(fetchMock).toHaveBeenCalledTimes(1)
  })

  it('shows the server message in an alert when the API says no', async () => {
    vi.stubGlobal('fetch', vi.fn(async () => jsonResponse({ error: 'Sign in required' }, 401)))
    render(<IssueListPage />)

    expect(await screen.findByRole('alert')).toHaveTextContent('Sign in required')
    expect(screen.queryByRole('status')).not.toBeInTheDocument()
    expect(screen.queryByRole('list')).not.toBeInTheDocument()
  })

  it('says it could not reach the server when the network itself fails', async () => {
    vi.stubGlobal('fetch', vi.fn(async () => { throw new TypeError('Failed to fetch') }))
    render(<IssueListPage />)

    expect(await screen.findByRole('alert')).toHaveTextContent('Could not reach the server')
  })

  it('shows a friendly empty message when there are no issues', async () => {
    installFakeApi([])
    render(<IssueListPage />)

    expect(await screen.findByText(/no issues yet/i)).toBeInTheDocument()
    expect(screen.queryByRole('alert')).not.toBeInTheDocument()
  })

  it('shows who reported each issue', async () => {
    installFakeApi()
    render(<IssueListPage />)
    await screen.findByText('Showing 4 of 4 issues')
    expect(screen.getAllByText('Reported by Eve Developer')).toHaveLength(4)
  })
})
